    16		);
    17	
    18		wire debug_clk;
    19	
    20		debug_clk clock(.clk(clk),.debug_en(debug_en),.debug_step(debug_step),.debug_clk(debug_clk));
    21	
    22	    wire Branch_ctrl, JALR, RegWrite_ctrl, mem_w_ctrl, mem_r_ctrl,
    23	        ALUSrc_A_ctrl, ALUSrc_B_ctrl, DatatoReg_ctrl, rs1use_ctrl, rs2use_ctrl,
    24	        MRET, csr_rw_ctrl, csr_w_imm_mux_ctrl;
    25	    wire[1:0] hazard_optype_ctrl, exp_vector_ctrl;
