  3	module HazardDetectionUnit(
  4	    input clk,
  5	    input Branch_ID, rs1use_ID, rs2use_ID,
  6	    input[1:0] hazard_optype_ID,
  7	    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
  8	    output PC_EN_IF, reg_FD_stall, reg_FD_flush, reg_DE_flush,
  9	    output forward_ctrl_ls,
 10	    output[1:0] forward_ctrl_A, forward_ctrl_B
 11	);
 12	
 13	    reg[1:0] hazard_optype_EXE, hazard_optype_MEM;
 14	    // 实现：把 ID 级的 hazard_optype 沿流水线打拍，跟踪 EXE / MEM 级指令的类型
 15	
 16	    localparam hazard_optype_ALU = 2'd1;
 17	    localparam hazard_optype_LOAD = 2'd2;
 18	    localparam hazard_optype_STORE = 2'd3;
 19	
 20	    // 实现：冒险检测与前递控制
 21	    // Detect forwarding conditions for rs1 and rs2 against EXE and MEM stages.
 22	    // Generate stall when load-use hazard is detected.
 23	    // Generate forwarding selectors for ALU-to-ID and MEM-to-ID forwarding.
 24	    // Generate load-store forwarding when store in EXE reads data produced by load in MEM.
 25	
 26	    initial begin
 27	        hazard_optype_EXE = 2'd0;
 28	        hazard_optype_MEM = 2'd0;
 29	    end
 30	
 31	    // ID 级的读寄存器需求
 32	    wire rs1_valid = rs1use_ID & (rs1_ID != 5'd0);
 33	    wire rs2_valid = rs2use_ID & (rs2_ID != 5'd0);
 34	
 35	    // EXE / MEM 级指令是否会写回寄存器
 36	    wire EXE_write = (hazard_optype_EXE == hazard_optype_ALU) |
 37	                     (hazard_optype_EXE == hazard_optype_LOAD);
 38	    wire MEM_write = (hazard_optype_MEM == hazard_optype_ALU) |
 39	                     (hazard_optype_MEM == hazard_optype_LOAD);
 40	
 41	    wire EXE_is_load = hazard_optype_EXE == hazard_optype_LOAD;
 42	    wire MEM_is_load = hazard_optype_MEM == hazard_optype_LOAD;
 43	
 44	    // 相关判断
 45	    wire rs1_EXE_conflict = rs1_valid & EXE_write & (rs1_ID == rd_EXE);
 46	    wire rs2_EXE_conflict = rs2_valid & EXE_write & (rs2_ID == rd_EXE);
 47	    wire rs1_MEM_conflict = rs1_valid & MEM_write & (rs1_ID == rd_MEM);
 48	    wire rs2_MEM_conflict = rs2_valid & MEM_write & (rs2_ID == rd_MEM);
 49	
 50	    // load-use 冒险：EXE 级是 load，ID 级需要它的结果 -> 必须暂停一拍。
 51	    // 例外：ID 级是 store 且只有 rs2（写入的数据）相关时，可以等到 EXE/MEM 级
 52	    //       再用 load-store 前递解决，不需要暂停。
 53	    wire ID_is_store = hazard_optype_ID == hazard_optype_STORE;
 54	    wire load_use_hazard = EXE_is_load &
 55	                           (rs1_EXE_conflict | (rs2_EXE_conflict & ~ID_is_store));
 56	
 57	    assign reg_FD_stall = load_use_hazard;
 58	    assign PC_EN_IF     = ~load_use_hazard;
 59	    assign reg_DE_flush = load_use_hazard;            // 向 EXE 级插入气泡
 60	    assign reg_FD_flush = Branch_ID & ~load_use_hazard;   // 跳转发生时清除已取的下一条指令
 61	
 62	    // 前递选择：00 = 寄存器堆, 01 = EXE 级 ALU 结果,
 63	    //           10 = MEM 级 ALU 结果, 11 = MEM 级 load 数据
 64	    assign forward_ctrl_A = rs1_EXE_conflict ? 2'b01 :
 65	                            rs1_MEM_conflict ? (MEM_is_load ? 2'b11 : 2'b10) :
 66	                            2'b00;
 67	    assign forward_ctrl_B = rs2_EXE_conflict ? 2'b01 :
 68	                            rs2_MEM_conflict ? (MEM_is_load ? 2'b11 : 2'b10) :
 69	                            2'b00;
 70	
 71	    // load-store 前递：EXE 级的 store 要写的数据来自 MEM 级 load 的结果
 72	    assign forward_ctrl_ls = (hazard_optype_EXE == hazard_optype_STORE) &
 73	                             MEM_is_load & (rs2_EXE != 5'd0) & (rs2_EXE == rd_MEM);
 74	
 75	    always @(posedge clk) begin
 76	        hazard_optype_EXE <= reg_DE_flush ? 2'd0 : hazard_optype_ID;
 77	        hazard_optype_MEM <= hazard_optype_EXE;
 78	    end
 79	
 80	endmodule`timescale 1ns / 1ps
