 82	module ALU(
 83	    input[31:0] A, B,
 84	    input[3:0] Control,
 85	    output[31:0] res,
 86	    output zero, overflow
 87	);
 88	
 89	    localparam ALU_ADD  = 4'b0001;
 90	    localparam ALU_SUB  = 4'b0010;
 91	    localparam ALU_AND  = 4'b0011;
 92	    localparam ALU_OR   = 4'b0100;
 93	    localparam ALU_XOR  = 4'b0101;
 94	    localparam ALU_SLL  = 4'b0110;
 95	    localparam ALU_SRL  = 4'b0111;
 96	    localparam ALU_SLT  = 4'b1000;
 97	    localparam ALU_SLTU = 4'b1001;
 98	    localparam ALU_SRA  = 4'b1010;
 99	    localparam ALU_Ap4  = 4'b1011;
100	    localparam ALU_Bout = 4'b1100;
101	
102	    // 实现：根据 Control 选择运算，并生成 zero / overflow 标志
103	    // The ALU must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
104	    // Use the Control input to select which operation to perform.
105	    // zero should be 1 when res is all zeros.
106	    // overflow should be set for signed ADD/SUB overflow.
107	
108	    wire[31:0] res_ADD  = A + B;
109	    wire[31:0] res_SUB  = A - B;
110	    wire[31:0] res_AND  = A & B;
111	    wire[31:0] res_OR   = A | B;
112	    wire[31:0] res_XOR  = A ^ B;
113	    wire[31:0] res_SLL  = A << B[4:0];
114	    wire[31:0] res_SRL  = A >> B[4:0];
115	    wire[31:0] res_SRA  = $signed(A) >>> B[4:0];
116	    wire       res_lt   = $signed(A) < $signed(B);
117	    wire       res_ltu  = A < B;
118	    wire[31:0] res_SLT  = {31'b0, res_lt};
119	    wire[31:0] res_SLTU = {31'b0, res_ltu};
120	    wire[31:0] res_Ap4  = A + 32'd4;
121	    wire[31:0] res_Bout = B;
122	
123	    wire is_ADD  = Control == ALU_ADD ;
124	    wire is_SUB  = Control == ALU_SUB ;
125	    wire is_AND  = Control == ALU_AND ;
126	    wire is_OR   = Control == ALU_OR  ;
127	    wire is_XOR  = Control == ALU_XOR ;
128	    wire is_SLL  = Control == ALU_SLL ;
129	    wire is_SRL  = Control == ALU_SRL ;
130	    wire is_SLT  = Control == ALU_SLT ;
131	    wire is_SLTU = Control == ALU_SLTU;
132	    wire is_SRA  = Control == ALU_SRA ;
133	    wire is_Ap4  = Control == ALU_Ap4 ;
134	    wire is_Bout = Control == ALU_Bout;
135	
136	    assign res = {32{is_ADD }} & res_ADD  |
137	                 {32{is_SUB }} & res_SUB  |
138	                 {32{is_AND }} & res_AND  |
139	                 {32{is_OR  }} & res_OR   |
140	                 {32{is_XOR }} & res_XOR  |
141	                 {32{is_SLL }} & res_SLL  |
142	                 {32{is_SRL }} & res_SRL  |
143	                 {32{is_SLT }} & res_SLT  |
144	                 {32{is_SLTU}} & res_SLTU |
145	                 {32{is_SRA }} & res_SRA  |
146	                 {32{is_Ap4 }} & res_Ap4  |
147	                 {32{is_Bout}} & res_Bout ;
148	
149	    assign zero = ~(|res);
150	
151	    assign overflow = is_ADD  & (~(A[31] ^ B[31]) & (res_ADD[31] ^ A[31])) |
152	                      is_SUB  & ( (A[31] ^ B[31]) & (res_SUB[31] ^ A[31])) ;
153	
154	endmodule`timescale 1ns / 1ps
