156	module ImmGen(
157	            input  wire [2:0] ImmSel,
158	            input  wire [31:0] inst_field,
159	            output[31:0] Imm_out
160	    );
161	    localparam Imm_type_I = 3'b001;
162	    localparam Imm_type_B = 3'b010;
163	    localparam Imm_type_J = 3'b011;
164	    localparam Imm_type_S = 3'b100;
165	    localparam Imm_type_U = 3'b101;
166	
167	    // 实现：根据 ImmSel 生成符号扩展后的立即数
168	    // Must handle I-type, B-type, J-type, S-type, and U-type immediate formats
169	    // following the RISC-V encoding specification.
170	    wire I = ImmSel == Imm_type_I;
171	    wire B = ImmSel == Imm_type_B;
172	    wire J = ImmSel == Imm_type_J;
173	    wire S = ImmSel == Imm_type_S;
174	    wire U = ImmSel == Imm_type_U;
175	
176	    wire[31:0] Imm_I = {{20{inst_field[31]}}, inst_field[31:20]};
177	    wire[31:0] Imm_B = {{20{inst_field[31]}}, inst_field[7], inst_field[30:25], inst_field[11:8], 1'b0};
178	    wire[31:0] Imm_J = {{12{inst_field[31]}}, inst_field[19:12], inst_field[20], inst_field[30:21], 1'b0};
179	    wire[31:0] Imm_S = {{20{inst_field[31]}}, inst_field[31:25], inst_field[11:7]};
180	    wire[31:0] Imm_U = {inst_field[31:12], 12'b0};
181	
182	    assign Imm_out = {32{I}} & Imm_I |
183	                     {32{B}} & Imm_B |
184	                     {32{J}} & Imm_J |
185	                     {32{S}} & Imm_S |
186	                     {32{U}} & Imm_U ;
187	endmodule
