209	module     Regs(input clk,
210					input rst,
211					input [4:0] R_addr_A, 
212					input [4:0] R_addr_B, 
213					input [4:0] Wt_addr, 
214					input [31:0]Wt_data, 
215					input L_S, 
216					output [31:0] rdata_A, 
217					output [31:0] rdata_B,
218					input [4:0] Debug_addr,         // debug address
219					output[31:0] Debug_regs        // debug data
220				  );
221	
222	reg [31:0] register [1:31]; 				// r1 - r31
223	integer i;
224	
225		// 实现：两读一写的寄存器堆
226		// - Reading two registers simultaneously (rdata_A, rdata_B)
227		// - Writing one register per cycle when L_S is asserted (write to Wt_addr with Wt_data)
228		// - x0 always reads as 0
229		// - Synchronous reset clears all registers to 0
230		// - Debug port reads register[Debug_addr] (0 if addr is 0)
231		assign rdata_A = (R_addr_A == 5'b0) ? 32'b0 : register[R_addr_A];	// read
232		assign rdata_B = (R_addr_B == 5'b0) ? 32'b0 : register[R_addr_B];	// read
233	
234		// 写口在时钟下降沿动作，使得同一周期 WB 写入的值可以被 ID 级立即读到
235		always @(negedge clk or posedge rst)
236		begin
237			if (rst) begin							// reset
238				for (i = 1; i < 32; i = i + 1)
239					register[i] <= 32'b0;
240			end
241			else begin
242				if ((Wt_addr != 5'b0) && (L_S == 1'b1))	// write
243					register[Wt_addr] <= Wt_data;
244			end
245		end
246	
247		assign Debug_regs = (Debug_addr == 5'b0) ? 32'b0 : register[Debug_addr];		//TEST
248	
249	endmodule
