254	module RAM_B(
255	    input [31:0] addra,
256	    input clka,      // normal clock
257	    input[31:0] dina,
258	    input wea, 
259	    output[31:0] douta,
260	    output [7:0] sim_uart_char_out,
261	    output sim_uart_char_valid,
262	    input[2:0] mem_u_b_h_w
263	);
264	    localparam SIZE = 256;
265	    localparam ADDR_LINE = $clog2(SIZE);
266	    localparam SIM_UART_ADDR = 32'h10000000;
267	
268	    reg[7:0] data[0:SIZE-1];
269	
270	    initial	begin
271	        $readmemh("ram.mem", data);
272	    end
273	
274	    // 地址译码：数据存储器只占用低地址空间，取地址低 ADDR_LINE 位
275	    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
276	    wire is_uart   = (addra == SIM_UART_ADDR);
277	    wire word_op   = mem_u_b_h_w[1];
278	    wire half_op   = mem_u_b_h_w[0];
279	    wire unsigned_op = mem_u_b_h_w[2];
280	
281	    // 实现：按字节写入
282	    // Write byte/halfword/word based on mem_u_b_h_w control signals.
283	    // mem_u_b_h_w[1]=1 means word, mem_u_b_h_w[0]=1 means halfword, otherwise byte.
284	    // Only write when wea is asserted. SIM_UART_ADDR writes should be excluded.
285	    always @(posedge clka) begin
286	        if (wea & ~is_uart) begin
287	            if (word_op) begin
288	                data[addr]                          <= dina[7:0];
289	                data[(addr + 1) % SIZE]             <= dina[15:8];
290	                data[(addr + 2) % SIZE]             <= dina[23:16];
291	                data[(addr + 3) % SIZE]             <= dina[31:24];
292	            end
293	            else if (half_op) begin
294	                data[addr]                          <= dina[7:0];
295	                data[(addr + 1) % SIZE]             <= dina[15:8];
296	            end
297	            else begin
298	                data[addr]                          <= dina[7:0];
299	            end
300	        end
301	    end
302	
303	    // 实现：按字节读出并做符号/零扩展
304	    // Read byte/halfword/word based on mem_u_b_h_w.
305	    // mem_u_b_h_w[2]=1 means unsigned (zero-extend), otherwise sign-extend.
306	    // Return 0 if address is SIM_UART_ADDR.
307	    wire[31:0] rdata_w = {data[(addr + 3) % SIZE], data[(addr + 2) % SIZE],
308	                          data[(addr + 1) % SIZE], data[addr]};
309	    wire[15:0] rdata_h = {data[(addr + 1) % SIZE], data[addr]};
310	    wire[7:0]  rdata_b = data[addr];
311	
312	    assign douta = is_uart ? 32'b0 :
313	                   word_op ? rdata_w :
314	                   half_op ? (unsigned_op ? {16'b0, rdata_h} : {{16{rdata_h[15]}}, rdata_h}) :
315	                             (unsigned_op ? {24'b0, rdata_b} : {{24{rdata_b[7]}},  rdata_b}) ;
316	
317	    // 实现：串口模拟输出
318	    // Detect writes to SIM_UART_ADDR, latch character data, and output via sim_uart_char_out.
319	    reg[7:0] uart_char_reg;
320	    reg      uart_valid_reg;
321	
322	    initial begin
323	        uart_char_reg  = 8'b0;
324	        uart_valid_reg = 1'b0;
325	    end
326	
327	    always @(posedge clka) begin
328	        if (wea & is_uart) begin
329	            uart_char_reg  <= dina[7:0];
330	            uart_valid_reg <= 1'b1;
331	            // 仿真时直接把字符打印到控制台
332	            // synthesis translate_off
333	            $write("%c", dina[7:0]);
334	            // synthesis translate_on
335	        end
336	        else begin
337	            uart_valid_reg <= 1'b0;
338	        end
339	    end
340	
341	    assign sim_uart_char_valid = uart_valid_reg;
342	    assign sim_uart_char_out   = uart_char_reg;
343	endmodule

